-- PT120-S3-Q11. Batch 03.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch03$PT120-S3-Q11$batch03$ AND q.stimulus=$batch03$Carrots are known to be one of the best sources of naturally occurring vitamin A. However, although farmers in Canada and the United States report increasing demand for carrots over the last decade, the number of people diagnosed with vitamin A deficiency in these countries has also increased in that time.$batch03$ AND q.prompt=$batch03$Each of the following, if true of Canada and the United States over the last decade, helps to resolve the apparent discrepancy described above EXCEPT:$batch03$ AND q.correct_choice=$batch03$C$batch03$) THEN RAISE EXCEPTION 'Question changed: PT120-S3-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch03$PT120-S3-Q11$batch03$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S3-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch03$PT120-S3-Q11$batch03$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch03$Given that$batch03$, $batch03$Carrots are a top source of vitamin A, and demand for carrots has risen.$batch03$), (1, $batch03$How can it be that$batch03$, $batch03$More people are being diagnosed with vitamin A deficiency?$batch03$), (2, $batch03$Evaluate$batch03$, $batch03$Routes: more people overall (more cases even at the same rate); carrots delivering less vitamin A; the extra carrots going to people who were not deficient; or fewer carrots actually eaten. Any of these lets demand rise while deficiency cases rise too.$batch03$), (3, $batch03$Goal$batch03$, $batch03$Four choices fit a route. The answer will make deficiency even harder to explain.$batch03$)) v(position,label,body) WHERE q.qid=$batch03$PT120-S3-Q11$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch03$A$batch03$, $batch03$A larger population means more diagnosed cases in total, even if the rate does not rise.$batch03$), ($batch03$B$batch03$, $batch03$Pre-cut carrots lose vitamins quickly, so people eating more carrots may get less vitamin A.$batch03$), ($batch03$C$batch03$, $batch03$Popular cuisines use more vegetables, including carrots. More carrots eaten should mean less deficiency, so this deepens the puzzle instead of resolving it.$batch03$), ($batch03$D$batch03$, $batch03$The extra carrots went to groups that rarely had deficiency, so the groups at risk saw no benefit.$batch03$), ($batch03$E$batch03$, $batch03$Demand rose but supply fell, so people may actually be eating fewer carrots.$batch03$)) v(letter,body) WHERE q.qid=$batch03$PT120-S3-Q11$batch03$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
